}

.filter-btn {
  padding: 12px 24px;
  border: 2px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  background: white;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.filter-btn:hover {
  border-color: var(--brand-green);
}

.locator-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.map-placeholder {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-weight: 600;
}

.store-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.store-card {
  padding: 20px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  transition: all 0.2s;
}

.store-card:hover {
  background: white;
  box-shadow: var(--shadow-sm);
}

.store-card h4 {
  margin: 0 0 8px;
  font-size: 16px;
}

.store-card p {
  margin: 0 0 8px;
  font-size: 14px;
  color: var(--text-secondary);
}

.store-card .hours {
  font-size: 13px;
  color: var(--brand-green);
}

.store-features {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.feature-tag {
  padding: 4px 10px;
  background: white;
  border-radius: 20px;
  font-size: 12px;
  color: var(--text-secondary);
}

/* Accordion footer */
.accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.accordion-header {
  width: 100%;
  padding: 16px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  color: white;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  text-align: left;
}

.accordion-header::after {
  content: '+';
  font-size: 20px;
  transition: transform 0.2s;
}

.accordion-item.open .accordion-header::after {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.accordion-item.open .accordion-content {
  max-height: 300px;
}

.accordion-content ul {
  list-style: none;
  padding: 0 0 16px 0;
  margin: 0;
}

.accordion-content li {
  padding: 8px 0;
}

.accordion-content a {
  color: rgba(255,255,255,0.7);
  font-size: 14px;
}

@media (max-width: 768px) {
  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .tier-cards {
    grid-template-columns: 1fr;
  }

  .locator-grid {
    grid-template-columns: 1fr;
  }

  .locator-controls {
    flex-direction: column;
  }

  .order-type-toggle {
    width: 100%;
  }

  .toggle-btn {
    flex: 1;
  }
}
