@import "tailwindcss";

:root {
  --brand-green: #00824A;
  --brand-forest: #32462F;
  --brand-cream: #F3CEA1;
  --brand-cream-dark: #E5B87A;
  --text-primary: #1a1a1a;
  --text-secondary: #5a5a5a;
  --bg-primary: #fff;
  --bg-secondary: #fafaf8;
  --accent: #00824A;
  --shadow-sm: 0 2px 8px rgba(0,0,0,0.08);
  --shadow-md: 0 4px 16px rgba(0,0,0,0.1);
  --shadow-lg: 0 8px 32px rgba(0,0,0,0.12);
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
}

@theme {
  --color-brand-green: #00824A;
  --color-brand-forest: #32462F;
  --color-brand-cream: #F3CEA1;
  --color-brand-cream-dark: #E5B87A;
}

@font-face {
  font-family: 'DM Sans';
  font-style: normal;
  font-weight: 400 700;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/dmsans/v15/rP2Hp2ywxg089UriI5-g4Xe7OcV5Kg.ttf) format('truetype');
}

@font-face {
  font-family: 'Plus Jakarta Sans';
  font-style: normal;
  font-weight: 600 800;
  font-display: swap;
  src: url(https://fonts.gstatic.com/s/plusjakartasans/v8/LDQiRwLn2bfQNYjMM-l9KkYcTmXQ-pVot8s9pW99E3uqdI83iBXXZNBX8.ttf) format('truetype');
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  margin: 0;
  font-family: 'DM Sans', system-ui, sans-serif;
  color: var(--text-primary);
  background: var(--bg-primary);
  -webkit-font-smoothing: antialiased;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Plus Jakarta Sans', 'DM Sans', system-ui, sans-serif;
  font-weight: 700;
  line-height: 1.2;
}

a {
  color: inherit;
  text-decoration: none;
}

.btn-primary {
  background: var(--brand-green);
  color: white;
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.btn-primary:hover {
  background: var(--brand-forest);
  transform: translateY(-1px);
  box-shadow: var(--shadow-md);
}

.btn-secondary {
  background: transparent;
  color: var(--brand-green);
  padding: 12px 24px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  border: 2px solid var(--brand-green);
  cursor: pointer;
  transition: all 0.2s;
}

.btn-secondary:hover {
  background: var(--brand-green);
  color: white;
}

.container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 0 24px;
}

/* Header */
.header {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  background: rgba(255,255,255,0.95);
  backdrop-filter: blur(10px);
  z-index: 100;
  border-bottom: 1px solid rgba(0,0,0,0.05);
}

.header-inner {
  max-width: 1200px;
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 8px;
  font-family: 'Plus Jakarta Sans', sans-serif;
  font-weight: 800;
  font-size: 20px;
  color: var(--brand-green);
}

.logo-icon {
  width: 36px;
  height: 36px;
  background: var(--brand-green);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.nav-links {
  display: flex;
  gap: 32px;
  list-style: none;
  margin: 0;
  padding: 0;
}

.nav-links a {
  font-weight: 500;
  color: var(--text-secondary);
  transition: color 0.2s;
}

.nav-links a:hover {
  color: var(--brand-green);
}

.nav-actions {
  display: flex;
  gap: 12px;
  align-items: center;
}

.btn-signin {
  padding: 10px 20px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  background: transparent;
  border: none;
  cursor: pointer;
  color: var(--text-primary);
}

.btn-signin:hover {
  background: var(--bg-secondary);
}

.btn-join {
  padding: 10px 20px;
  border-radius: var(--radius-lg);
  font-weight: 600;
  background: var(--brand-green);
  color: white;
  border: none;
  cursor: pointer;
  transition: all 0.2s;
}

.btn-join:hover {
  background: var(--brand-forest);
}

/* Hero */
.hero {
  padding: 140px 24px 80px;
  background: linear-gradient(135deg, var(--brand-cream) 0%, #fff 50%, rgba(0,130,74,0.05) 100%);
  position: relative;
  overflow: hidden;
}

.hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 600px;
  height: 600px;
  background: radial-gradient(circle, rgba(0,130,74,0.08) 0%, transparent 70%);
  border-radius: 50%;
}

.hero-content {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 60px;
  align-items: center;
}

.hero-text h1 {
  font-size: 56px;
  font-weight: 800;
  color: var(--text-primary);
  margin: 0 0 20px;
  letter-spacing: -1px;
}

.hero-text p {
  font-size: 18px;
  color: var(--text-secondary);
  margin: 0 0 32px;
  line-height: 1.6;
}

.hero-cta {
  display: flex;
  gap: 16px;
}

.hero-visual {
  position: relative;
  height: 450px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.hero-image-placeholder {
  width: 100%;
  height: 100%;
  background: linear-gradient(135deg, var(--brand-green) 0%, var(--brand-forest) 100%);
  border-radius: var(--radius-xl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: white;
  font-size: 18px;
  font-weight: 600;
}

/* Section styling */
.section {
  padding: 80px 24px;
}

.section-cream {
  background: var(--brand-cream);
}

.section-green {
  background: var(--brand-green);
  color: white;
}

.section-forest {
  background: var(--brand-forest);
  color: white;
}

.section-header {
  text-align: center;
  margin-bottom: 48px;
}

.section-header h2 {
  font-size: 36px;
  margin: 0 0 12px;
}

.section-header p {
  font-size: 18px;
  color: var(--text-secondary);
}

/* Cards */
.card-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
}

.card {
  background: white;
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: all 0.3s;
}

.card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.card-image {
  height: 180px;
  background: linear-gradient(135deg, var(--brand-cream) 0%, var(--brand-cream-dark) 100%);
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--brand-forest);
  font-weight: 600;
}

.card-body {
  padding: 24px;
}

.card-body h3 {
  font-size: 20px;
  margin: 0 0 8px;
}

.card-body p {
  color: var(--text-secondary);
  line-height: 1.5;
  margin: 0 0 16px;
}

/* Footer */
.footer {
  background: var(--brand-forest);
  color: white;
  padding: 60px 24px 30px;
}

.footer-grid {
  max-width: 1200px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 40px;
}

.footer-col h4 {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 1px;
  margin: 0 0 16px;
  opacity: 0.7;
}

.footer-col ul {
  list-style: none;
  padding: 0;
  margin: 0;
}

.footer-col li {
  margin-bottom: 10px;
}

.footer-col a {
  color: rgba(255,255,255,0.8);
  font-size: 14px;
  transition: color 0.2s;
}

.footer-col a:hover {
  color: white;
}

.footer-bottom {
  max-width: 1200px;
  margin: 40px auto 0;
  padding-top: 24px;
  border-top: 1px solid rgba(255,255,255,0.1);
  display: flex;
  justify-content: space-between;
  align-items: center;
  font-size: 14px;
  color: rgba(255,255,255,0.6);
}

/* Mobile menu */
.mobile-menu-btn {
  display: none;
  background: none;
  border: none;
  cursor: pointer;
  padding: 8px;
}

/* Cookie Banner */
.cookie-banner {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  background: white;
  padding: 20px 24px;
  box-shadow: 0 -4px 20px rgba(0,0,0,0.1);
  z-index: 200;
  display: none;
}

.cookie-banner.show {
  display: block;
}

.cookie-inner {
  max-width: 1200px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 24px;
}

.cookie-text h4 {
  margin: 0 0 4px;
  font-size: 16px;
}

.cookie-text p {
  margin: 0;
  font-size: 14px;
  color: var(--text-secondary);
}

.cookie-actions {
  display: flex;
  gap: 12px;
}

/* Responsive */
@media (max-width: 1024px) {
  .hero-content {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .hero-text h1 {
    font-size: 42px;
  }

  .hero-cta {
    justify-content: center;
  }

  .hero-visual {
    height: 300px;
  }

  .card-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-grid {
    grid-template-columns: repeat(3, 1fr);
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }

  .mobile-menu-btn {
    display: block;
  }

  .hero {
    padding: 120px 24px 60px;
  }

  .hero-text h1 {
    font-size: 32px;
  }

  .section {
    padding: 60px 24px;
  }

  .section-header h2 {
    font-size: 28px;
  }

  .card-grid {
    grid-template-columns: 1fr;
  }

  .footer-grid {
    grid-template-columns: repeat(2, 1fr);
  }

  .footer-bottom {
    flex-direction: column;
    gap: 12px;
    text-align: center;
  }

  .cookie-inner {
    flex-direction: column;
    text-align: center;
  }
}

/* Menu page */
.menu-layout {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 40px;
  padding: 120px 24px 80px;
  max-width: 1200px;
  margin: 0 auto;
}

.menu-sidebar {
  position: sticky;
  top: 100px;
  height: fit-content;
}

.menu-category-list {
  list-style: none;
  padding: 0;
  margin: 0;
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  overflow: hidden;
}

.menu-category-list li {
  border-bottom: 1px solid rgba(0,0,0,0.05);
}

.menu-category-list li:last-child {
  border-bottom: none;
}

.menu-category-list a {
  display: block;
  padding: 14px 20px;
  font-weight: 500;
  transition: all 0.2s;
}

.menu-category-list a:hover {
  background: white;
  color: var(--brand-green);
}

.menu-category-list .sub {
  color: var(--text-secondary);
  font-size: 14px;
}

.menu-content h2 {
  font-size: 28px;
  margin: 0 0 24px;
}

.menu-items {
  display: grid;
  gap: 16px;
}

.menu-item {
  display: flex;
  gap: 16px;
  padding: 16px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  transition: all 0.2s;
}

.menu-item:hover {
  background: white;
  box-shadow: var(--shadow-sm);
}

.menu-item-image {
  width: 80px;
  height: 80px;
  background: var(--brand-cream);
  border-radius: var(--radius-sm);
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  color: var(--brand-forest);
}

.menu-item-details h4 {
  margin: 0 0 4px;
  font-size: 16px;
}

.menu-item-details p {
  margin: 0;
  font-size: 14px;
  color: var(--text-secondary);
}

/* Rewards page */
.rewards-hero {
  padding: 140px 24px 80px;
  background: linear-gradient(135deg, var(--brand-forest) 0%, var(--brand-green) 100%);
  color: white;
  text-align: center;
}

.rewards-hero h1 {
  font-size: 48px;
  margin: 0 0 16px;
}

.rewards-hero p {
  font-size: 20px;
  opacity: 0.9;
  max-width: 600px;
  margin: 0 auto;
}

.tier-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 24px;
  margin-bottom: 60px;
}

.tier-card {
  background: white;
  border-radius: var(--radius-lg);
  padding: 32px;
  text-align: center;
}

.tier-card h3 {
  color: var(--brand-green);
  font-size: 24px;
  margin: 0 0 8px;
}

.tier-card .stars {
  font-size: 16px;
  color: var(--text-secondary);
  margin: 0 0 16px;
}

.tier-card ul {
  list-style: none;
  padding: 0;
  margin: 0;
  text-align: left;
}

.tier-card li {
  padding: 8px 0;
  border-bottom: 1px solid rgba(0,0,0,0.05);
  font-size: 14px;
  color: var(--text-secondary);
}

.tier-card li:last-child {
  border-bottom: none;
}

/* Tabs */
.tabs {
  display: flex;
  gap: 4px;
  background: var(--bg-secondary);
  padding: 4px;
  border-radius: var(--radius-lg);
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.tab {
  padding: 12px 20px;
  border-radius: var(--radius-md);
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  background: transparent;
  color: var(--text-secondary);
}

.tab:hover {
  color: var(--text-primary);
}

.tab.active {
  background: var(--brand-green);
  color: white;
}

.tab-content {
  display: none;
  animation: fadeIn 0.3s ease;
}

.tab-content.active {
  display: block;
}

@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.redemption-card {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  padding: 32px;
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.redemption-info h3 {
  font-size: 28px;
  color: var(--brand-green);
  margin: 0 0 8px;
}

.redemption-info p {
  color: var(--text-secondary);
  margin: 0;
}

/* Gift page */
.gift-hero {
  padding: 140px 24px 60px;
  background: linear-gradient(135deg, var(--brand-cream) 0%, white 100%);
  text-align: center;
}

.gift-hero h1 {
  font-size: 48px;
  color: var(--text-primary);
  margin: 0 0 16px;
}

.gift-hero p {
  font-size: 18px;
  color: var(--text-secondary);
  max-width: 600px;
  margin: 0 auto;
}

.carousel-section {
  padding: 40px 24px;
}

.carousel-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 24px;
}

.carousel-header h2 {
  font-size: 24px;
  margin: 0;
}

.carousel-nav {
  display: flex;
  gap: 8px;
}

.carousel-btn {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  border: 2px solid var(--brand-green);
  background: white;
  color: var(--brand-green);
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s;
}

.carousel-btn:hover {
  background: var(--brand-green);
  color: white;
}

.carousel {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 16px;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
}

.carousel::-webkit-scrollbar {
  display: none;
}

.gift-card {
  flex-shrink: 0;
  width: 200px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  overflow: hidden;
  scroll-snap-align: start;
  transition: all 0.2s;
}

.gift-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-md);
}

.gift-card-image {
  height: 120px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 600;
  font-size: 14px;
}

.gift-card-body {
  padding: 16px;
  text-align: center;
}

.gift-card-body h4 {
  font-size: 14px;
  margin: 0 0 4px;
}

.gift-card-body p {
  font-size: 12px;
  color: var(--text-secondary);
  margin: 0;
}

/* Store locator */
.locator-layout {
  padding: 120px 24px 80px;
  max-width: 1200px;
  margin: 0 auto;
}

.locator-controls {
  display: flex;
  gap: 16px;
  margin-bottom: 24px;
  flex-wrap: wrap;
}

.search-input {
  flex: 1;
  min-width: 250px;
  padding: 14px 20px;
  border: 2px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  font-size: 16px;
  font-family: inherit;
  transition: border-color 0.2s;
}

.search-input:focus {
  outline: none;
  border-color: var(--brand-green);
}

.order-type-toggle {
  display: flex;
  background: var(--bg-secondary);
  padding: 4px;
  border-radius: var(--radius-lg);
}

.toggle-btn {
  padding: 12px 24px;
  border-radius: var(--radius-md);
  font-weight: 600;
  cursor: pointer;
  transition: all 0.2s;
  border: none;
  background: transparent;
  color: var(--text-secondary);
}

.toggle-btn.active {
  background: var(--brand-green);
  color: white;
}

.filter-btn {
  padding: 12px 24px;
  border: 2px solid rgba(0,0,0,0.1);
  border-radius: var(--radius-lg);
  background: white;
  font-weight: 600;
  cursor: pointer;
  display: flex;
  align-items: center;
  gap: 8px;
  transition: all 0.2s;
}

.filter-btn:hover {
  border-color: var(--brand-green);
}

.locator-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 24px;
}

.map-placeholder {
  background: var(--bg-secondary);
  border-radius: var(--radius-lg);
  height: 500px;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--text-secondary);
  font-weight: 600;
}

.store-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.store-card {
  padding: 20px;
  background: var(--bg-secondary);
  border-radius: var(--radius-md);
  transition: all 0.2s;
}

.store-card:hover {
  background: white;
  box-shadow: var(--shadow-sm);
}

.store-card h4 {
  margin: 0 0 8px;
  font-size: 16px;
}

.store-card p {
  margin: 0 0 8px;
  font-size: 14px;
  color: var(--text-secondary);
}

.store-card .hours {
  font-size: 13px;
  color: var(--brand-green);
}

.store-features {
  display: flex;
  gap: 8px;
  margin-top: 12px;
}

.feature-tag {
  padding: 4px 10px;
  background: white;
  border-radius: 20px;
  font-size: 12px;
  color: var(--text-secondary);
}

/* Accordion footer */
.accordion-item {
  border-bottom: 1px solid rgba(255,255,255,0.1);
}

.accordion-header {
  width: 100%;
  padding: 16px 0;
  display: flex;
  justify-content: space-between;
  align-items: center;
  background: none;
  border: none;
  color: white;
  font-size: 14px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  cursor: pointer;
  text-align: left;
}

.accordion-header::after {
  content: '+';
  font-size: 20px;
  transition: transform 0.2s;
}

.accordion-item.open .accordion-header::after {
  transform: rotate(45deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.accordion-item.open .accordion-content {
  max-height: 300px;
}

.accordion-content ul {
  list-style: none;
  padding: 0 0 16px 0;
  margin: 0;
}

.accordion-content li {
  padding: 8px 0;
}

.accordion-content a {
  color: rgba(255,255,255,0.7);
  font-size: 14px;
}

@media (max-width: 768px) {
  .menu-layout {
    grid-template-columns: 1fr;
  }

  .menu-sidebar {
    position: static;
  }

  .tier-cards {
    grid-template-columns: 1fr;
  }

  .locator-grid {
    grid-template-columns: 1fr;
  }

  .locator-controls {
    flex-direction: column;
  }

  .order-type-toggle {
    width: 100%;
  }

  .toggle-btn {
    flex: 1;
  }
}

